style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-image: url("https://i.postimg.cc/wTvm032R/Yellow-Strawberry-phone-background.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
  }

  /* Si no aparece, probemos con estos estilos más generales */
  * {
    background-image: url("https://i.postimg.cc/wTvm032R/Yellow-Strawberry-phone-background.jpg") !important; 
    background-size: cover !important;
  }
}
